from cardio_1 import a, G
# Abréviations nouvelles du cours I77 (dysplasie fibromusculaire et autres atteintes des artères).
a('SVM',[('S','Society for'),('V','Vascular'),('M','Medicine')],'Society for Vascular Medicine (société américaine de médecine vasculaire)','<p>Société savante américaine de médecine vasculaire ; co-auteure, avec le groupe de travail « Hypertension and the Kidney » de la Société européenne d’hypertension, du premier consensus international sur la dysplasie fibromusculaire (2019). Le texte conjoint est cosigné par une société européenne.</p>')
a('ARCADIA',[('A','Assessment of'),('R','Renal'),('A','And'),('C','Cervical'),('A','Artery'),('DIA','DysplAsia')],'Registre français ARCADIA (évaluation de la dysplasie des artères rénales et cervicales)','<p>Registre et étude français de la dysplasie fibromusculaire, coordonnés à l’Hôpital européen Georges-Pompidou à Paris ; il a montré, par imagerie systématique, la fréquence des atteintes multivasculaires. Une déclinaison polonaise existe (ARCADIA-POL).</p>')
a('PHACTR1',[('PHACTR','PHosphatase and ACTin Regulator'),('1','1')],'Gène PHACTR1 (régulateur de la phosphatase et de l’actine 1)','<p>Gène de la région chromosomique 6p24 ; un variant fréquent situé dans l’un de ses introns (rs9349379-A) augmente le risque de dysplasie fibromusculaire, de dissection des artères cervicales, d’hypertension et de migraine, et protège de la maladie coronaire athéroscléreuse.</p>')
a('MBq',[('MBq','pseudonyme d’un contributeur de Wikimedia Commons, non une abréviation')],'Pseudonyme de l’auteur d’une image de Wikimedia Commons','<p>Nom d’utilisateur de l’auteur de l’angioscanner de compression du tronc cœliaque, versé dans le domaine public sur Wikimedia Commons. Dans d’autres contextes, le même sigle désigne le mégabecquerel, unité d’activité radioactive.</p>')
